//! 🎯️ The shared controller uses the real retained session, finite original caller and decoder through full physical closure.
use semio_os_flow_host_session::{FlowEvalSession,FlowEvaluationPipeline};
use semio_framework_artifact_flow_flow::FlowHostSnapshot;
use neural_engine::{self as neural,OperatorInfo};
use protocol::causal::transition::HistoryFoldIndex;
use semio_framework_value::{RetirementDemand,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep};
use semio_framework_value::retirement::RetireOwned;
use std::sync::Arc;
#[global_allocator]
static HEAP:semio_framework_trace::HeapWitness=semio_framework_trace::HeapWitness;
use semio_framework_job::{OriginalJobFixtureCaller,OriginalJobDecodeOwner,OriginalTurnFailure,OperationId,Generation,StepContext,close_original_retained_step};
use semio_framework_value::retained_clone::RetainedCloneClose;
use semio_framework_value::RetainedWorkOutcome;
fn observe<T>(run:impl FnOnce()->T)->(T,usize,usize){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(run);assert!(!heap.overflowed);(value,heap.requested_bytes,heap.released_bytes)}
struct TurnResult<T>{inner:Option<Result<T,OriginalTurnFailure>>,outer:Result<(),OriginalTurnFailure>}
impl<T> TurnResult<T>{fn unwrap(self)->T{self.outer.unwrap();self.inner.expect("original closing callback must run").unwrap()}}
fn turn<T>(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,grant:RetainedCloneGrant,loan:Option<u64>,births:&mut usize,releases:&mut usize,cpu:&mut bool,run:impl FnOnce(&mut StepContext<'_>)->Result<T,OriginalTurnFailure>)->TurnResult<T>{
 let mut inner=None;let before=caller.fuel_remaining();let(outer,b,f)=observe(||caller.turn_with_decoder(grant,decoder,|cx|{let body=|same:&mut StepContext<'_>|{inner=Some(run(same));Ok(())};if let Some(fuel)=loan{let deadline=cx.original_absolute_deadline_us();cx.with_original_work_loan(fuel,deadline,body)}else{body(cx)}}));
 let p=caller.receipt();assert_eq!((b,f),(p.retained_capacity_bytes,p.released_bytes));*births+=b;*releases+=f;*cpu&=loan.is_none_or(|fuel|before-caller.fuel_remaining()<=fuel);TurnResult{inner,outer}
}
#[derive(semio_framework_value::RetireOwned)]
struct Sources{snapshot:FlowHostSnapshot,infos:Arc<HistoryFoldIndex<String,OperatorInfo>>,registry:neural::SharedRegistry,pending:Option<Vec<neural::PendingExtensionEval>>,failure:Option<OriginalTurnFailure>,outer_failure:Option<OriginalTurnFailure>}
fn close<T:RetireOwned>(value:T,caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,g:RetainedCloneGrant,loan:Option<u64>,births:&mut usize,releases:&mut usize,cpu:&mut bool,turns:&mut usize){
 let mut value=Some(value);let mut owner=RetainedCloneClose::default();for _ in 0..32768{if value.is_none()&&owner.is_empty(){return}*turns+=1;turn(caller,decoder,g,loan,births,releases,cpu,|cx|cx.with_original_retirement(|cx|{for _ in 0..512{let before=(cx.fuel_remaining(),cx.retained_progress());let d=owner.next_owner_demands::<T>(value.is_some(),&None,cx.retained_grant().maximum_copy_bytes)?;close_original_retained_step(cx,d,|grant|if owner.is_empty(){let turn=owner.begin_granted(&mut value,grant);RetainedWorkOutcome{result:turn.result.map(|step|step.unwrap_or(RetainedCloneStep::Progress(Default::default()))),work:turn.work}}else{owner.step_granted(grant)})?;if (value.is_none()&&owner.is_empty())||cx.should_yield()||before==(cx.fuel_remaining(),cx.retained_progress()){break}}Ok(())})).unwrap();}panic!("original controller must finish physical closure")
}
#[test]
fn original_shared_pipeline_publishes_to_the_real_session_and_closes_with_the_existing_stock(){run(None)}
#[test]
fn original_shared_pipeline_keeps_the_existing_opportunity_under_one_fuel_and_512_items(){run(Some(1))}
fn run(loan:Option<u64>){
 let fixture:serde_json::Value=serde_json::from_str(semio_framework_test_fixtures::repo_text!("🧰️framework/🛍️products/💻️os/🔨️modules/🌊️flow/🖥️host/📤️publication/🧵️work/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();
 let policy:serde_json::Value=serde_json::from_str(semio_framework_test_fixtures::repo_text!("🧰️framework/🛍️products/💻️os/🔨️modules/🔌️plugin/🧪️testing/🎟️caller/🧪️tests/🧫️fixtures/🎟️caller.json")).unwrap();
 let stock:RetainedCloneGrant=serde_json::from_value(policy["grant"].clone()).unwrap();assert_eq!(stock.maximum_items,512);assert_eq!(policy["fuel"],32768);
 for cancel_at in [None,Some(0),Some(1),Some(5),Some(37)]{
  let((mut sources,mut session,mut registry_retirement),b,f)=observe(||{let snapshot=semio_framework_pack_json::from_json_str(&fixture["source"].to_string(),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();let(registry,retirement)=neural::SharedRegistry::new(neural::Registry::new());let session=FlowEvalSession::new().with_operator_registry(registry.clone());(Sources{snapshot,infos:Arc::new(HistoryFoldIndex::new()),registry,pending:None,failure:None,outer_failure:None},session,retirement)});
  let original=b-f;let(mut births,mut releases,mut turns,mut cpu)=(0,0,0,true);let pointer=sources.snapshot.widgets.as_ptr();
  let mut caller=OriginalJobFixtureCaller::admit(OperationId(policy["operation"].as_u64().unwrap()),Generation(policy["generation"].as_u64().unwrap()),stock,||Some(1000),1500,32768);let caller_birth=caller.born_bytes();let mut decoder=OriginalJobDecodeOwner::empty();
  let(mut pipeline,b,f)=observe(||FlowEvaluationPipeline::new(session.evaluation_work(sources.infos.clone(),19).unwrap()));assert_eq!((b,f),(0,0));let mut completed=false;let mut unchanged=true;let mut quoted=true;
  for index in 0..200{if cancel_at==Some(index){caller.cancel().cancel_now();break}turns+=1;let quote=pipeline.next_demands(&sources.snapshot,&sources.infos,&session,stock.maximum_copy_bytes).unwrap();let answer=turn(&mut caller,&mut decoder,stock,loan,&mut births,&mut releases,&mut cpu,|cx|{let before=cx.retained_progress();let answer=pipeline.step(&sources.snapshot,&sources.infos,&mut session,cx);let after=cx.retained_progress();if loan.is_some(){quoted&=after.copied_bytes.checked_sub(before.copied_bytes).is_some_and(|n|n<=quote.copy_bytes)&&after.retained_capacity_bytes.checked_sub(before.retained_capacity_bytes).is_some_and(|n|n<=quote.capacity_bytes)&&after.released_bytes.checked_sub(before.released_bytes).is_some_and(|n|n<=quote.release_bytes)}answer});unchanged&=pointer==sources.snapshot.widgets.as_ptr();if let Err(error)=answer.outer{sources.outer_failure=Some(error)}match answer.inner{Some(Ok(Some(output)))=>{unchanged&=output.pending.is_empty()&&!output.unfinished;sources.pending=Some(output.pending);completed=true;break},Some(Ok(None))=>{},Some(Err(error))=>{sources.failure=Some(error);break},None=>break}if sources.outer_failure.is_some(){break}}
  let matched=cancel_at.is_some()||completed&&serde_json::from_str::<serde_json::Value>(session.eval_json()).unwrap()==fixture["expected"]&&session.painted_eval_json()==session.eval_json()&&session.converged_eval_json()==session.eval_json();
  pipeline.begin_close();for _ in 0..32768{if pipeline.terminal_is_empty(){break}turns+=1;turn(&mut caller,&mut decoder,stock,loan,&mut births,&mut releases,&mut cpu,|cx|cx.with_original_retirement(|cx|{for _ in 0..512{let before=(cx.fuel_remaining(),cx.retained_progress());pipeline.close_step(cx)?;if pipeline.terminal_is_empty()||cx.should_yield()||before==(cx.fuel_remaining(),cx.retained_progress()){break}}Ok(())})).unwrap();}assert!(pipeline.terminal_is_empty());assert_eq!(observe(||drop(pipeline)),((),0,0));
  session.begin_close();for _ in 0..32768{if session.terminal_is_empty(){break}turns+=1;turn(&mut caller,&mut decoder,stock,loan,&mut births,&mut releases,&mut cpu,|cx|cx.with_original_retirement(|cx|{for _ in 0..512{let before=(cx.fuel_remaining(),cx.retained_progress());let copy=cx.retained_grant().maximum_copy_bytes;let d=RetirementDemand{copy_bytes:session.next_close_copy_byte_demand()?,capacity_bytes:session.next_close_capacity_byte_demand(copy)?,release_bytes:session.next_close_release_byte_demand()?,depth:session.next_close_depth_demand()?};close_original_retained_step(cx,d,|grant|session.retire_source_step(grant))?;if session.terminal_is_empty()||cx.should_yield()||before==(cx.fuel_remaining(),cx.retained_progress()){break}}Ok(())})).unwrap();}assert!(session.terminal_is_empty());assert_eq!(observe(||drop(session)),((),0,0));
  let no_failure=sources.failure.is_none()&&sources.outer_failure.is_none();close(sources,&mut caller,&mut decoder,stock,loan,&mut births,&mut releases,&mut cpu,&mut turns);
  for _ in 0..32768{if registry_retirement.terminal_is_empty(){break}turns+=1;turn(&mut caller,&mut decoder,stock,loan,&mut births,&mut releases,&mut cpu,|cx|cx.with_original_retirement(|cx|{for _ in 0..512{let before=(cx.fuel_remaining(),cx.retained_progress());let copy=cx.retained_grant().maximum_copy_bytes;let d=RetirementDemand{copy_bytes:registry_retirement.next_copy_byte_demand()?,capacity_bytes:registry_retirement.next_capacity_byte_demand(copy)?,release_bytes:registry_retirement.next_release_byte_demand()?,depth:registry_retirement.next_depth_demand()?};close_original_retained_step(cx,d,|grant|{let result=registry_retirement.close_step(grant);RetainedWorkOutcome{result,work:registry_retirement.last_turn_work()}})?;if registry_retirement.terminal_is_empty()||cx.should_yield()||before==(cx.fuel_remaining(),cx.retained_progress()){break}}Ok(())})).unwrap();}assert!(registry_retirement.terminal_is_empty());
  for _ in 0..32768{if decoder.terminal_is_empty(){break}turns+=1;let before=caller.fuel_remaining();let(result,b,f)=observe(||caller.turn(stock,|cx|cx.with_original_retirement(|cx|{let mut run=|cx:&mut StepContext<'_>|{let d=decoder.retirement_demands(cx.retained_grant().maximum_copy_bytes)?;decoder.close_on_source(cx)?;Ok(())};if let Some(fuel)=loan{let deadline=cx.original_absolute_deadline_us();cx.with_original_work_loan(fuel,deadline,run)}else{run(cx)}})));let p=caller.receipt();assert_eq!((b,f),(p.retained_capacity_bytes,p.released_bytes));births+=b;releases+=f;cpu&=loan.is_none_or(|fuel|before-caller.fuel_remaining()<=fuel);result.unwrap();}
  assert!(decoder.terminal_is_empty());for _ in 0..32768{if caller.terminal_is_empty(){break}turns+=1;let d=caller.retirement_demands().unwrap();let(p,b,f)=observe(||caller.retire_step(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}).unwrap().progress());assert_eq!((b,f),(p.retained_capacity_bytes,p.released_bytes));births+=b;releases+=f;}
  assert!(caller.terminal_is_empty());assert_eq!(caller.stock(),stock);assert_eq!(original+caller_birth+births,releases);assert!(matched&&unchanged&&no_failure&&cpu&&quoted);assert!(turns<=200,"original full controller and physical family exceeded its unchanged opportunity");
 }
}
